// info.cpp - Shows the size of data in memory
#include <iostream>
using namespace std;

int main() {
    cout << "Size of char  : " << sizeof(char)   << " byte"  << endl;
    cout << "Size of int   : " << sizeof(int)    << " bytes" << endl;
    cout << "Size of float : " << sizeof(float)  << " bytes" << endl;
    cout << "Size of double: " << sizeof(double) << " bytes" << endl;
    return 0;
}

// convert.cpp - GB to MB, KB, bytes and bits
#include <iostream>
using namespace std;

int main() {
    double gb;
    cout << "Enter size in GB: ";
    cin >> gb;

    double mb    = gb * 1024;
    double kb    = mb * 1024;
    double bytes = kb * 1024;
    double bits  = bytes * 8;

    cout << "MB    = " << mb    << endl;
    cout << "KB    = " << kb    << endl;
    cout << "Bytes = " << bytes << endl;
    cout << "Bits  = " << bits  << endl;
    return 0;
}

